import java.nio.file.*;import java.util.*;import java.lang.reflect.*;import com.google.gson.*;import org.joml.Matrix4f;import net.minecraft.resources.Identifier;import io.github.r3neer.scalebrews.collision.pose.*;import io.github.r3neer.scalebrews.collision.api.spi.PoseEngine;import io.github.r3neer.scalebrews.collision.geometry.ModelGeometry;
public final class S60Consumer {
 static int assertions=0;static void check(boolean b,String why){assertions++;if(!b)throw new AssertionError("S60 "+why);}
 static final class Resources implements PoseEngine.Resources {FinitePoseProgram table;Map<String,NumericPoseProgram> numeric;int tables,codes;Resources(FinitePoseProgram t,Map<String,NumericPoseProgram> n){table=t;numeric=n;}public Optional<PoseProgram> program(Identifier i){return Optional.empty();}public Optional<FinitePoseProgram> finiteProgram(Identifier i){tables++;return Optional.ofNullable(table);}public Optional<NumericPoseProgram> numericProgram(Identifier i){codes++;return Optional.ofNullable(numeric.get(i.toString()));}}
 static PoseEngine.Inputs inputs(Map<String,Float> c){return new PoseEngine.Inputs(0,0,0,0,0,true,c);}static void rejected(Runnable r,String why){try{r.run();throw new AssertionError("S60 admitted "+why);}catch(IllegalArgumentException expected){assertions++;}}
 static void detached(Object o,Set<Object> seen)throws Exception{if(o==null||!seen.add(o))return;check(!(o instanceof Resources||o instanceof ModelGeometry||o instanceof NumericPoseProgram||o instanceof FinitePoseProgram),"retained preparation object "+o.getClass());if(o instanceof Iterable<?> a){for(Object v:a)detached(v,seen);return;}if(o instanceof Map<?,?> a){for(Object v:a.values())detached(v,seen);return;}if(o.getClass().isArray()){if(!o.getClass().getComponentType().isPrimitive())for(Object v:(Object[])o)detached(v,seen);return;}if(o.getClass().getName().startsWith("io.github.r3neer.scalebrews"))for(Field f:o.getClass().getDeclaredFields()){if(!Modifier.isStatic(f.getModifiers())){f.setAccessible(true);detached(f.get(o),seen);}}}
 public static void main(String[]args)throws Exception{
  var g=new Gson();var families=JsonParser.parseString(Files.readString(Path.of(args[0]))).getAsJsonArray();var reports=JsonParser.parseString(Files.readString(Path.of(args[1]))).getAsJsonArray();int matrices=0;var allResults=new ArrayList<Object>();
  for(int familyIndex=0;familyIndex<families.size();familyIndex++){
   var f=families.get(familyIndex).getAsJsonObject();var table=FinitePoseProgram.validatedCopy(g.fromJson(f.get("table"),FinitePoseProgram.class));var numeric=new TreeMap<String,NumericPoseProgram>();f.getAsJsonObject("numericPrograms").entrySet().forEach(e->numeric.put(e.getKey(),NumericPoseProgram.validatedCopy(g.fromJson(e.getValue(),NumericPoseProgram.class))));var geom=numeric.firstEntry().getValue().geometry();var required=new TreeSet<String>(table.booleans());for(var v:numeric.values())for(var n:v.nodes())if(n.op()==NumericPoseProgram.Op.INPUT)required.add(n.input());var r=new Resources(table,numeric);var engine=new FinitePoseEngine();var parameters=Map.of("program",f.get("tableId").getAsString());var bound=engine.bind(geom,parameters,required,r).orElseThrow();check(r.tables==1&&r.codes==numeric.size(),"bind unique counts");detached(bound,Collections.newSetFromMap(new IdentityHashMap<>()));
   var results=new ArrayList<Object>();Map<String,Float> first=null;
   for(int j=0;j<table.rows().size();j++){var report=reports.get(familyIndex*table.rows().size()+j).getAsJsonObject();for(var element:report.getAsJsonArray("samples")){var sample=element.getAsJsonObject();var c=new TreeMap<String,Float>();sample.getAsJsonObject("channels").entrySet().forEach(e->c.put(e.getKey(),e.getValue().getAsFloat()));if(first==null)first=new TreeMap<>(c);var actual=geom.transforms(bound.evaluate(inputs(c)).orElseThrow());var expected=sample.getAsJsonObject("matrices");check(actual.keySet().equals(expected.keySet()),"parts");for(var id:actual.keySet()){check(actual.get(id).equals(new Matrix4f().set(g.fromJson(expected.get(id),float[].class)),3e-6f),"native matrix "+id);matrices++;}results.add(actual.entrySet().stream().collect(java.util.stream.Collectors.toMap(Map.Entry::getKey,e->ModelGeometry.values(e.getValue()))));}}
   for(String name:table.booleans())for(float v:new float[]{-0f,.5f,Math.nextDown(1f),Math.nextUp(1f),-1f,2f}){var c=new TreeMap<>(first);c.put(name,v);check(bound.evaluate(inputs(c)).isEmpty(),"nonboolean bits "+v);}for(String name:required){var c=new TreeMap<>(first);c.remove(name);check(bound.evaluate(inputs(c)).isEmpty(),"missing declared "+name);}check(engine.evaluate(geom,inputs(first),parameters).isEmpty(),"direct authority");
   var missing=new TreeMap<>(numeric);missing.remove(table.rows().getLast().program());check(engine.bind(geom,parameters,required,new Resources(table,missing)).isEmpty(),"inactive missing resource");var overlap=new TreeMap<>(numeric);var base=numeric.firstEntry().getValue();var nodes=new ArrayList<>(base.nodes());for(int k=0;k<nodes.size();k++){var n=nodes.get(k);if(n.op()==NumericPoseProgram.Op.INPUT){nodes.set(k,new NumericPoseProgram.Node(n.op(),n.left(),n.right(),n.constant(),table.booleans().getFirst(),n.part(),n.field()));break;}}overlap.put(numeric.firstKey(),new NumericPoseProgram(base.format(),base.source(),base.version(),base.geometry(),nodes,base.writes()));check(engine.bind(geom,parameters,required,new Resources(table,overlap)).isEmpty(),"bool reused as arithmetic");
   r.table=null;r.numeric=Map.of();for(int k=0;k<100000;k++)check(bound.evaluate(inputs(first)).isPresent(),"detached repeated evaluation");check(r.tables==1&&r.codes==numeric.size(),"hot resource lookup");allResults.add(results);
  }
  var valid=g.fromJson(families.get(0).getAsJsonObject().get("table"),FinitePoseProgram.class);var ids=valid.rows().stream().map(FinitePoseProgram.Row::program).toList();rejected(()->new FinitePoseProgram(1,"x","1",List.of("b","a"),valid.rows()),"unsorted booleans");rejected(()->new FinitePoseProgram(1,"x","1",valid.booleans(),valid.rows().subList(0,valid.rows().size()-1)),"partial rows");var duplicates=new ArrayList<>(valid.rows());duplicates.set(duplicates.size()-1,duplicates.getFirst());rejected(()->new FinitePoseProgram(1,"x","1",valid.booleans(),duplicates),"duplicate mask");rejected(()->FinitePoseProgram.resourceId("a:"+"a".repeat(255)),"oversized id");var zero=new FinitePoseProgram(1,"x","1",List.of(),List.of(new FinitePoseProgram.Row(0,ids.getFirst())));check(zero.rows().size()==1,"zero booleans");var rows=new ArrayList<FinitePoseProgram.Row>();for(int i=31;i>=0;i--)rows.add(new FinitePoseProgram.Row(i,ids.getFirst()));var max=new FinitePoseProgram(1,"x","1",List.of("a","b","c","d","e"),rows);check(max.rows().getFirst().mask()==0&&max.rows().getLast().mask()==31,"canonical max rows");
  var baseObject=families.get(0).getAsJsonObject().getAsJsonObject("numericPrograms").entrySet().iterator().next();var geometry=g.fromJson(baseObject.getValue(),NumericPoseProgram.class).geometry();var maxPrograms=new TreeMap<String,NumericPoseProgram>();var maxRows=new ArrayList<FinitePoseProgram.Row>();for(int i=0;i<32;i++){String id="s60:mask_"+i;var program=new NumericPoseProgram(1,"max-mask","1",geometry,List.of(new NumericPoseProgram.Node(NumericPoseProgram.Op.CONSTANT,-1,-1,i,null,null,-1)),List.of(new NumericPoseProgram.Write(geometry.parts().getFirst().id(),0,0)));maxPrograms.put(id,program);maxRows.add(new FinitePoseProgram.Row(i,id));}var maxTable=new FinitePoseProgram(1,"max-mask","1",List.of("a","b","c","d","e"),maxRows);var maxResources=new Resources(maxTable,maxPrograms);var maxBound=new FinitePoseEngine().bind(geometry,Map.of("program","s60:max"),Set.of("a","b","c","d","e"),maxResources).orElseThrow();for(int i=0;i<32;i++){var channels=new TreeMap<String,Float>();for(int bit=0;bit<5;bit++)channels.put(maxTable.booleans().get(bit),(i&(1<<bit))!=0?1f:0f);check(maxBound.evaluate(inputs(channels)).orElseThrow().get(geometry.parts().getFirst().id()).m30()==i/16f,"maximum mask exact "+i);}check(maxResources.tables==1&&maxResources.codes==32,"maximum cold lookups");
  var good=maxPrograms.get("s60:mask_2");var poison=new NumericPoseProgram(1,"inactive-arithmetic","1",geometry,List.of(new NumericPoseProgram.Node(NumericPoseProgram.Op.CONSTANT,-1,-1,1,null,null,-1),new NumericPoseProgram.Node(NumericPoseProgram.Op.CONSTANT,-1,-1,0,null,null,-1),new NumericPoseProgram.Node(NumericPoseProgram.Op.DIVIDE,0,1,0,null,null,-1)),List.of(new NumericPoseProgram.Write(geometry.parts().getFirst().id(),0,2)));var poisonResources=new Resources(new FinitePoseProgram(1,"inactive","1",List.of("gate"),List.of(new FinitePoseProgram.Row(0,"s60:good"),new FinitePoseProgram.Row(1,"s60:poison"))),Map.of("s60:good",good,"s60:poison",poison));var lazy=new FinitePoseEngine().bind(geometry,Map.of("program","s60:lazy"),Set.of("gate"),poisonResources).orElseThrow();check(lazy.evaluate(inputs(Map.of("gate",0f))).isPresent(),"inactive arithmetic evaluated eagerly");check(lazy.evaluate(inputs(Map.of("gate",1f))).isEmpty(),"selected nonfinite arithmetic admitted");
  var tooMany=new AbstractList<String>(){public int size(){return 6;}public String get(int i){throw new AssertionError("S60 traversed oversized boolean list");}};rejected(()->new FinitePoseProgram(1,"cap","1",tooMany,maxRows),"boolean cap before traversal");check(FinitePoseProgram.resourceId("s60:"+"a".repeat(252)).length()==256,"ID exact cap");
  Files.writeString(Path.of("common-matrices.json"),new GsonBuilder().setPrettyPrinting().create().toJson(allResults));System.out.println("S60_COMMON_PASS families="+families.size()+" matrices="+matrices+" assertions="+assertions+" clientVeto=true resourcesAfterBind=0");
 }
}
